import { SVGProps } from "react";

type MistralIconProps = SVGProps<SVGSVGElement> & { size?: number };

export default function MistralAiIcon({
  size = 24,
  ...props
}: MistralIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      <image
        href="data:image/png;base64,"
        width="24"
        height="24"
        x="0"
        y="0"
        preserveAspectRatio="xMidYMid slice"
      />
    </svg>
  );
}
